mapper.select:
SELECT r.rslt_id, e.excn_dt, e.anls_param_json ->> 'plcyType' AS plcy_type, e.anls_param_json ->> 'expandMethod' AS expand_method, (e.anls_param_json ->> 'addPkltSlot')::int AS add_pklt_slot, (e.anls_param_json ->> 'predcMm')::int AS predc_mm, e.anls_param_json ->> 'sggNm' AS sgg_nm, e.anls_param_json ->> 'emdCd' AS emd_cd, (e.anls_param_json -> 'vrblAjmt')::text AS vrbl_ajmt_json, r.anls_rng_cn, r.crtr_cvlcpt_cnt, r.crtr_ilgl_cnt, r.crtr_cngst_idx, r.exs_pklt_cpcty, r.vld_add_pklt_slot, r.cvlcpt_rdct_rt, r.cngst_impv_rt, r.aftr_cngst_idx, r.aftr_cvlcpt_cnt, r.calc_stts_cd, r.excs_yn, r.cst_lvl_cd, r.road_mtnc_type, r.road_mtnc_len, r.adjc_cvlcpt_cnt, r.fee_aplcn_mthd, r.fee_aplcn_zone, r.fee_incrs_rt, r.aplcn_trgt_slot, r.lvng_vhcl_cnt, r.absrp_cnt, r.trnsf_cnt, r.aplcn_param_json::text AS aplcn_param_json FROM parking.tb_plcy_smlt_rslt r JOIN parking.tb_anls_excn e ON e.excn_id = r.excn_id WHERE e.anls_type_cd = 'POLICY_SIM' AND e.excutr_id = #{userId}
AND r.rslt_id IN #{id}
AND false

SELECT a.emd_cd, a.emd_nm, COALESCE(SUM(p.pklt_cpcty), 0) AS aplcn_trgt_slot FROM parking.tb_admdst a LEFT JOIN parking.tb_pblpklt p ON p.emd_cd = a.emd_cd AND p.ownshp_type_nm IS DISTINCT FROM '민영' AND p.extsh_dt IS NULL AND COALESCE(p.prk_crg_yn, 'N') = #{crgYn} WHERE 1=1
AND a.emd_cd = #{emdCd}
AND a.emd_nm !~ '(읍|면)$' AND a.emd_nm ~ '(읍|면)$' AND a.sgg_nm = #{sggNm}
GROUP BY a.emd_cd, a.emd_nm
